const fs = require("node:fs");
const migrations = [
  "001_platform.sql",
  "002_learning_release.sql",
  "003_community.sql",
  "004_services.sql",
  "005_quiz_retry.sql",
  "006_feature_workflows.sql",
  "007_service_integrity.sql",
  "008_identity_community.sql",
  "009_timed_quiz.sql",
  "010_learning_media.sql",
  "011_admin_signup.sql",
  "012_study_assistant.sql",
];
const output =
  "-- Education Forum 1.1.0: one-time setup for a project without app tables.\n" +
  "-- Run the entire file in the Supabase SQL Editor. Do not run on an existing installation.\n" +
  "-- Generated by node scripts/prepare-supabase.cjs; canonical sources are migrations/*.sql.\n\nbegin;\n" +
  migrations
    .map(
      (name) =>
        `\n-- ${name}\n${fs.readFileSync(`supabase/migrations/${name}`, "utf8")}\n`,
    )
    .join("") +
  "\nnotify pgrst, 'reload schema';\ncommit;\n";
fs.writeFileSync("supabase/SETUP.sql", output);
console.log("Prepared supabase/SETUP.sql from all migrations.");
